set statement_timeout='20s';
select jsonb_build_object('now',now(),
'rel_locks',(select coalesce(jsonb_agg(jsonb_build_object('rel',l.relation::regclass::text,'pid',l.pid,'mode',l.mode,'granted',l.granted,'state',a.state,'usename',a.usename,'app',a.application_name,'bt',a.backend_type,'xact_start',a.xact_start,'q',left(a.query,100))),'[]') from pg_locks l left join pg_stat_activity a on a.pid=l.pid where l.pid<>pg_backend_pid() and l.locktype='relation' and l.relation in (select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','supabase_migrations','cron')) and l.mode not in ('AccessShareLock','RowShareLock') ),
'blocked',(select coalesce(jsonb_agg(jsonb_build_object('pid',pid,'blocked_by',pg_blocking_pids(pid),'state',state,'wait',wait_event_type||':'||wait_event,'q',left(query,100))),'[]') from pg_stat_activity where cardinality(pg_blocking_pids(pid))>0),
'long_xacts',(select coalesce(jsonb_agg(jsonb_build_object('pid',pid,'usename',usename,'app',application_name,'state',state,'xact_start',xact_start,'wait',wait_event_type||':'||wait_event,'q',left(query,100)) order by xact_start),'[]') from pg_stat_activity where xact_start < now()-interval '30 seconds' and pid<>pg_backend_pid() and backend_type='client backend'),
'advisory_waiting',(select count(*) from pg_locks where locktype='advisory' and not granted),
'migration_text',(select coalesce(jsonb_agg(jsonb_build_object('pid',pid,'state',state,'q',left(query,80))),'[]') from pg_stat_activity where query ilike '%hosted-migration%' and pid<>pg_backend_pid())) a;
